<?php
require __DIR__.'/../app/bootstrap.php';$article=null;$related=[];$error='';
try{$article=one('SELECT * FROM articles WHERE slug=? AND published_at IS NOT NULL AND published_at<=NOW()',[query('slug')]);if($article)$related=rows('SELECT slug,title FROM articles WHERE category=? AND id<>? AND published_at<=NOW() ORDER BY published_at DESC LIMIT 3',[$article['category'],$article['id']]);else http_response_code(404);}catch(Throwable $e){error_log($e->getMessage());http_response_code(503);$error='Artikel belum dapat dimuat.';}
require __DIR__.'/../resources/views/components/header.php';?>
<main class="public-page"><?php if($article): ?><div class="page-heading"><p class="eyebrow"><?= e($article['category']) ?></p><h1><?= e($article['title']) ?></h1><p><?= e($article['published_at']) ?> WIB</p></div><?php if($photo=safeUrl($article['image'])): ?><img src="<?= e($photo) ?>" alt="Ilustrasi artikel" style="width:100%;max-height:460px;object-fit:cover;border-radius:20px;margin-bottom:30px"><?php endif; ?><article class="panel article-body"><?= e($article['body']) ?></article><?php if($related): ?><h2 class="section-title" style="margin:40px 0 20px">Artikel terkait</h2><div class="portal-grid"><?php foreach($related as $item): ?><a class="panel" href="article.php?slug=<?= e($item['slug']) ?>"><h3><?= e($item['title']) ?></h3></a><?php endforeach; ?></div><?php endif; ?><?php else: ?><div class="empty"><h1><?= e($error?:'Artikel tidak ditemukan atau belum diterbitkan.') ?></h1></div><?php endif; ?><div class="actions"><a href="insights.php" class="btn secondary">Kembali ke artikel</a></div></main>
<?php require __DIR__.'/../resources/views/components/footer.php'; ?>
